# SIAMS-ALPHA-M1: generated by setup-alpha-apps.sh, safe to edit (re-runs skip it)
"""Helpers for assessment tests (and for Team Beta if they ever need a rubric)."""

import json
from pathlib import Path

from apps.assessments.importers import AssessmentFormImporter
from apps.placements.services import PeriodService

EXAMPLES = Path(__file__).resolve().parents[1] / "examples"

DEFAULT_BANDS = [
    {"min_percent": "70", "label": "A"},
    {"min_percent": "60", "label": "B"},
    {"min_percent": "0", "label": "F"},
]


def load_example(name: str) -> dict:
    return json.loads((EXAMPLES / name).read_text(encoding="utf-8"))


def make_forms(period, with_bands: bool = True):
    """Import example workplace (60%) and academic (40%) forms."""
    workplace = AssessmentFormImporter.import_json(
        period, load_example("example_workplace_form.json")
    )
    academic = AssessmentFormImporter.import_json(
        period, load_example("example_academic_form.json")
    )
    if with_bands:
        PeriodService.set_grade_bands(period, DEFAULT_BANDS)
    return workplace, academic


def full_scores(form, ratio: float = 1.0) -> list[dict]:
    """A complete, valid score list: every SCORE criterion at `ratio` of its maximum."""
    items = []
    for criterion in form.criteria.all():
        if criterion.type == "SCORE":
            items.append(
                {"criterion": criterion.id, "score": int(criterion.max_score * ratio), "remark": ""}
            )
        else:
            items.append({"criterion": criterion.id, "score": None, "remark": "Good intern."})
    return items
